1	import { AppConfig, ChatOptions, MLCEngineConfig } from "./config";
2	import {
3	  MLCEngineInterface,
4	  InitProgressCallback,
5	  InitProgressReport,
6	  LogLevel,
7	  LogitProcessor,
8	} from "./types";
9	import {
10	  ChatCompletionRequest,
11	  ChatCompletionRequestBase,
12	  ChatCompletionRequestStreaming,
13	  ChatCompletionRequestNonStreaming,
14	  ChatCompletion,
15	  ChatCompletionChunk,
16	  Completion,
17	  CompletionCreateParamsNonStreaming,
18	  CompletionCreateParamsStreaming,
19	  CompletionCreateParamsBase,
20	  CompletionCreateParams,
21	  CreateEmbeddingResponse,
22	  EmbeddingCreateParams,
23	} from "./openai_api_protocols/index";
24	import * as API from "./openai_api_protocols/index";
25	import {
26	  MessageContent,
27	  ReloadParams,
28	  ForwardTokensAndSampleParams,
29	  ChatCompletionNonStreamingParams,
30	  ChatCompletionStreamInitParams,
31	  ResetChatParams,
32	  WorkerResponse,
33	  WorkerRequest,
34	  CompletionNonStreamingParams,
35	  EmbeddingParams,
36	  CompletionStreamInitParams,
37	  GetMessageParams,
38	  RuntimeStatsTextParams,
39	  CompletionStreamNextChunkParams,
40	} from "./message";
41	import log from "loglevel";
42	import { MLCEngine } from "./engine";
43	import {
44	  UnknownMessageKindError,
45	  WorkerEngineModelNotLoadedError,
46	} from "./error";
47	import { areArraysEqual } from "./utils";
48	import { getModelIdToUse } from "./support";
49	
50	/**
51	 * Worker handler that can be used in a WebWorker
52	 *
53	 * @example
54	 *
55	 * // setup a chat worker handler that routes
56	 * // requests to the chat
57	 * const engine = new MLCEngine();
58	 * cont handler = new WebWorkerMLCEngineHandler(engine);
59	 * onmessage = handler.onmessage;
60	 */
61	export class WebWorkerMLCEngineHandler {
62	  /**
63	   * The modelId and chatOpts that the underlying engine (backend) is currently loaded with.
64	   * An engine can be loaded with multiple models, so modelId and chatOpts are lists.
65	   *
66	   * TODO(webllm-team): This is always in-sync with `this.engine` unless device is lost due to
67	   * unexpected reason. Therefore, we should get it from `this.engine` directly and make handler
68	   * stateless. Besides, consider if we should add appConfig, or use engine's API to find the
69	   * corresponding model record rather than relying on just the modelId.
70	   */
71	  modelId?: string[];
72	  chatOpts?: ChatOptions[];
73	
74	  public engine: MLCEngine;
75	  /** ChatCompletion and Completion share the same chunk generator. Each loaded model has its own. */
76	  protected loadedModelIdToAsyncGenerator: Map<
77	    string,
78	    AsyncGenerator<ChatCompletionChunk | Completion, void, void>
79	  >;
80	
81	  /**
82	   * @param engine A concrete implementation of MLCEngineInterface
83	   */
84	  constructor() {
85	    this.engine = new MLCEngine();
86	    this.loadedModelIdToAsyncGenerator = new Map<
87	      string,
88	      AsyncGenerator<ChatCompletionChunk | Completion, void, void>
89	    >();
90	    this.engine.setInitProgressCallback((report: InitProgressReport) => {
91	      const msg: WorkerResponse = {
92	        kind: "initProgressCallback",
93	        uuid: "",
94	        content: report,
95	      };
96	      this.postMessage(msg);
97	    });
98	  }
99	
100	  postMessage(msg: any) {
101	    // Use Web Worker DOM Message API
102	    postMessage(msg);
103	  }
104	
105	  setLogitProcessorRegistry(
106	    logitProcessorRegistry?: Map<string, LogitProcessor>,
107	  ) {
108	    this.engine.setLogitProcessorRegistry(logitProcessorRegistry);
109	  }
110	
111	  async handleTask<T extends MessageContent>(
112	    uuid: string,
113	    task: () => Promise<T>,
114	  ) {
115	    try {
116	      const res = await task();
117	      const msg: WorkerResponse = {
118	        kind: "return",
119	        uuid: uuid,
120	        content: res,
121	      };
122	      this.postMessage(msg);
123	    } catch (err) {
124	      const errStr = (err as object).toString();
125	      const msg: WorkerResponse = {
126	        kind: "throw",
127	        uuid: uuid,
128	        content: errStr,
129	      };
130	      this.postMessage(msg);
131	    }
132	  }
133	
134	  onmessage(
135	    event: any,
136	    onComplete?: (value: any) => void,
137	    onError?: () => void,
138	  ) {
139	    let msg: WorkerRequest;
140	    if (event instanceof MessageEvent) {
141	      msg = event.data as WorkerRequest;
142	    } else {
143	      msg = event as WorkerRequest;
144	    }
145	    switch (msg.kind) {
146	      case "reload": {
147	        this.handleTask(msg.uuid, async () => {
148	          const params = msg.content as ReloadParams;
149	          await this.engine.reload(params.modelId, params.chatOpts);
150	          this.modelId = params.modelId;
151	          this.chatOpts = params.chatOpts;
152	          onComplete?.(null);
153	          return null;
154	        });
155	        return;
156	      }
157	      case "forwardTokensAndSample": {
158	        this.handleTask(msg.uuid, async () => {
159	          const params = msg.content as ForwardTokensAndSampleParams;
160	          const res = await this.engine.forwardTokensAndSample(
161	            params.inputIds,
162	            params.isPrefill,
163	            params.modelId,
164	          );
165	          onComplete?.(res);
166	          return res;
167	        });
168	        return;
169	      }
170	      // For engine.chat.completions.create()
171	      case "chatCompletionNonStreaming": {
172	        // Directly return the ChatCompletion response
173	        this.handleTask(msg.uuid, async () => {
174	          const params = msg.content as ChatCompletionNonStreamingParams;
175	          await this.reloadIfUnmatched(params.modelId, params.chatOpts);
176	          const res = await this.engine.chatCompletion(params.request);
177	          onComplete?.(res);
178	          return res;
179	        });
180	        return;
181	      }
182	      case "chatCompletionStreamInit": {
183	        // One-time set up that instantiates the chunk generator in worker
184	        this.handleTask(msg.uuid, async () => {
185	          const params = msg.content as ChatCompletionStreamInitParams;
186	          // Also ensures params.selectedModelId will match what this.engine selects
187	          await this.reloadIfUnmatched(params.modelId, params.chatOpts);
188	          // Register new async generator for this new request of the model
189	          const curGenerator = (await this.engine.chatCompletion(
190	            params.request,
191	          )) as AsyncGenerator<ChatCompletionChunk, void, void>;
192	          this.loadedModelIdToAsyncGenerator.set(
193	            params.selectedModelId,
194	            curGenerator,
195	          );
196	          onComplete?.(null);
197	          return null;
198	        });
199	        return;
200	      }
201	      // For engine.completions.create()
202	      case "completionNonStreaming": {
203	        // Directly return the ChatCompletion response
204	        this.handleTask(msg.uuid, async () => {
205	          const params = msg.content as CompletionNonStreamingParams;
206	          await this.reloadIfUnmatched(params.modelId, params.chatOpts);
207	          const res = await this.engine.completion(params.request);
208	          onComplete?.(res);
209	          return res;
210	        });
211	        return;
212	      }
213	      case "completionStreamInit": {
214	        // One-time set up that instantiates the chunk generator in worker
215	        this.handleTask(msg.uuid, async () => {
216	          const params = msg.content as CompletionStreamInitParams;
217	          // Also ensures params.selectedModelId will match what this.engine selects
218	          await this.reloadIfUnmatched(params.modelId, params.chatOpts);
219	          // Register new async generator for this new request of the model
220	          const curGenerator = (await this.engine.completion(
221	            params.request,
222	          )) as AsyncGenerator<Completion, void, void>;
223	          this.loadedModelIdToAsyncGenerator.set(
224	            params.selectedModelId,
225	            curGenerator,
226	          );
227	          onComplete?.(null);
228	          return null;
229	        });
230	        return;
231	      }
232	      // Shared by engine.chat.completions.create() and engine.completions.create()
233	      case "completionStreamNextChunk": {
234	        // Note: ChatCompletion and Completion share the same chunk generator.
235	        // For any subsequent request, we return whatever `next()` yields
236	        this.handleTask(msg.uuid, async () => {
237	          const params = msg.content as CompletionStreamNextChunkParams;
238	          const curGenerator = this.loadedModelIdToAsyncGenerator.get(
239	            params.selectedModelId,
240	          );
241	          if (curGenerator === undefined) {
242	            throw Error(
243	              "InternalError: Chunk generator in worker should be instantiated by now.",
244	            );
245	          }
246	          // Yield the next chunk
247	          const { value } = await curGenerator.next();
248	          onComplete?.(value);
249	          return value;
250	        });
251	        return;
252	      }
253	      // For engine.embeddings.create()
254	      case "embedding": {
255	        // Directly return the Embeddings response
256	        this.handleTask(msg.uuid, async () => {
257	          const params = msg.content as EmbeddingParams;
258	          await this.reloadIfUnmatched(params.modelId, params.chatOpts);
259	          const res = await this.engine.embedding(params.request);
260	          onComplete?.(res);
261	          return res;
262	        });
263	        return;
264	      }
265	      case "runtimeStatsText": {
266	        this.handleTask(msg.uuid, async () => {
267	          const params = msg.content as RuntimeStatsTextParams;
268	          const res = await this.engine.runtimeStatsText(params.modelId);
269	          onComplete?.(res);
270	          return res;
271	        });
272	        return;
273	      }
274	      case "interruptGenerate": {
275	        this.handleTask(msg.uuid, async () => {
276	          this.engine.interruptGenerate();
277	          onComplete?.(null);
278	          return null;
279	        });
280	        return;
281	      }
282	      case "unload": {
283	        // Unset modelId and chatOpts since backend unloads the model
284	        this.handleTask(msg.uuid, async () => {
285	          await this.engine.unload();
286	          this.modelId = undefined;
287	          this.chatOpts = undefined;
288	          // This may not be cleaned properly when one asyncGenerator finishes.
289	          // We only clear at unload(), which may not be called upon reload().
290	          // However, service_worker may skip reload(). Will leave as is for now.
291	          this.loadedModelIdToAsyncGenerator.clear();
292	          onComplete?.(null);
293	          return null;
294	        });
295	        return;
296	      }
297	      case "resetChat": {
298	        this.handleTask(msg.uuid, async () => {
299	          const params = msg.content as ResetChatParams;
300	          await this.engine.resetChat(params.keepStats, params.modelId);
301	          onComplete?.(null);
302	          return null;
303	        });
304	        return;
305	      }
306	      case "getMaxStorageBufferBindingSize": {
307	        this.handleTask(msg.uuid, async () => {
308	          const res = await this.engine.getMaxStorageBufferBindingSize();
309	          onComplete?.(res);
310	          return res;
311	        });
312	        return;
313	      }
314	      case "getGPUVendor": {
315	        this.handleTask(msg.uuid, async () => {
316	          const res = await this.engine.getGPUVendor();
317	          onComplete?.(res);
318	          return res;
319	        });
320	        return;
321	      }
322	      case "getMessage": {
323	        this.handleTask(msg.uuid, async () => {
324	          const params = msg.content as GetMessageParams;
325	          const res = await this.engine.getMessage(params.modelId);
326	          onComplete?.(res);
327	          return res;
328	        });
329	        return;
330	      }
331	      case "setLogLevel": {
332	        const logLevel = msg.content as LogLevel;
333	        this.engine.setLogLevel(logLevel);
334	        log.setLevel(logLevel);
335	        onComplete?.(null);
336	        return;
337	      }
338	      case "setAppConfig": {
339	        const appConfig = msg.content as AppConfig;
340	        this.engine.setAppConfig(appConfig);
341	        onComplete?.(null);
342	        return;
343	      }
344	      case "customRequest": {
345	        onComplete?.(null);
346	        return;
347	      }
348	      default: {
349	        if (msg.kind && msg.content) {
350	          onError?.();
351	          throw new UnknownMessageKindError(msg.kind, msg.content);
352	        } else {
353	          // Ignore irrelavent events
354	          onComplete?.(null);
355	        }
356	      }
357	    }
358	  }
359	
360	  /** Check whether frontend expectation matches with backend (modelId and chatOpts). If not (due
361	   * to possibly killed service worker), we reload here.
362	   * For more, see https://github.com/mlc-ai/web-llm/pull/533
363	   */
364	  async reloadIfUnmatched(
365	    expectedModelId: string[],
366	    expectedChatOpts?: ChatOptions[],
367	  ) {
368	    // TODO: should we also check expectedChatOpts here?
369	    if (!areArraysEqual(this.modelId, expectedModelId)) {
370	      log.warn(
371	        "WebWorkerMLCEngine expects model is loaded in WebWorkerMLCEngineHandler, " +
372	          "but it is not. This may due to web/service worker is unexpectedly killed.\n" +
373	          "Reloading engine in WebWorkerMLCEngineHandler.",
374	      );
375	      await this.engine.reload(expectedModelId, expectedChatOpts);
376	    }
377	  }
378	}
379	
380	export interface ChatWorker {
381	  onmessage: any;
382	  postMessage: (message: any) => void;
383	}
384	
385	/**
386	 * Creates `WebWorkerMLCEngine`, a client that holds the same interface as `MLCEngine`.
387	 *
388	 * Equivalent to `new webllm.WebWorkerMLCEngine(worker).reload(...)`.
389	 *
390	 * @param worker The worker that holds the actual MLCEngine, initialized with `new Worker()`.
391	 * @param modelId model_id of the model to load, either string or string[]. When multiple models
392	 *   are provided, we load all models sequentially. Each modelId needs to either be in
393	 *   `webllm.prebuiltAppConfig`, or in `engineCOnfig.appConfig`.
394	 * @param engineConfig Optionally configures the engine, see `webllm.MLCEngineConfig` for more.
395	 * @param chatOpts Extra options to optionally override the `mlc-chat-config.json` of `modelId`.
396	 *   The size of which needs to match that of `modelId`; chatOpts[i] will be used for modelId[i].
397	 * @returns An initialized `WebLLM.WebWorkerMLCEngine` with `modelId` loaded.
398	 *
399	 * @note engineConfig.logitProcessorRegistry is ignored for `CreateWebWorkMLCEngine()`.
400	 */
401	export async function CreateWebWorkerMLCEngine(
402	  worker: any,
403	  modelId: string | string[],
404	  engineConfig?: MLCEngineConfig,
405	  chatOpts?: ChatOptions | ChatOptions[],
406	): Promise<WebWorkerMLCEngine> {
407	  const webWorkerMLCEngine = new WebWorkerMLCEngine(worker, engineConfig);
408	  await webWorkerMLCEngine.reload(modelId, chatOpts);
409	  return webWorkerMLCEngine;
410	}
411	
412	/**
413	 * A client of MLCEngine that exposes the same interface
414	 *
415	 * @example
416	 *
417	 * const chat = new webllm.WebWorkerMLCEngine(new Worker(
418	 *   new URL('./worker.ts', import.meta.url),
419	 *   {type: 'module'}
420	 * ));
421	 */
422	export class WebWorkerMLCEngine implements MLCEngineInterface {
423	  public worker: ChatWorker;
424	  /** For chat.completions.create() */
425	  public chat: API.Chat;
426	  /** For completions.create() */
427	  public completions: API.Completions;
428	  /** For embeddings.create() */
429	  public embeddings: API.Embeddings;
430	
431	  /**
432	   * The modelId and chatOpts that the frontend expects the backend engine is currently loaded
433	   * with. Needed for service worker. It is the backend and handler's job to match up with the
434	   * expectation despite the web/service worker possibly being killed.
435	   * Since an engine can load multiple models, both modelId and chatOpts are lists.
436	   */
437	  modelId?: string[];
438	  chatOpts?: ChatOptions[];
439	
440	  private initProgressCallback?: InitProgressCallback;
441	  private pendingPromise = new Map<string, (msg: WorkerResponse) => void>();
442	
443	  constructor(worker: ChatWorker, engineConfig?: MLCEngineConfig) {
444	    this.worker = worker;
445	    worker.onmessage = (event: any) => {
446	      this.onmessage.bind(this)(event);
447	    };
448	
449	    if (engineConfig?.appConfig) {
450	      this.setAppConfig(engineConfig?.appConfig);
451	    }
452	    if (engineConfig?.logLevel) {
453	      this.setLogLevel(engineConfig?.logLevel);
454	    }
455	    this.setInitProgressCallback(engineConfig?.initProgressCallback);
456	    if (engineConfig?.logitProcessorRegistry) {
457	      if (engineConfig?.logitProcessorRegistry) {
458	        log.warn(
459	          "Warning: The `logitProcessorRegistry` property in `engineConfig` will be ignored when using the WebWorkerMLCEngine constructor. To set `logitProcessorRegistry`, use the engine constructor within the worker script instead.",
460	        );
461	      }
462	    }
463	
464	    this.chat = new API.Chat(this);
465	    this.completions = new API.Completions(this);
466	    this.embeddings = new API.Embeddings(this);
467	  }
468	
469	  setInitProgressCallback(initProgressCallback?: InitProgressCallback) {
470	    this.initProgressCallback = initProgressCallback;
471	  }
472	
473	  getInitProgressCallback(): InitProgressCallback | undefined {
474	    return this.initProgressCallback;
475	  }
476	
477	  setAppConfig(appConfig: AppConfig) {
478	    const msg: WorkerRequest = {
479	      kind: "setAppConfig",
480	      uuid: crypto.randomUUID(),
481	      content: appConfig,
482	    };
483	    this.worker.postMessage(msg);
484	  }
485	
486	  setLogLevel(logLevel: LogLevel) {
487	    log.setLevel(logLevel);
488	    const msg: WorkerRequest = {
489	      kind: "setLogLevel",
490	      uuid: crypto.randomUUID(),
491	      content: logLevel,
492	    };
493	    this.worker.postMessage(msg);
494	  }
495	
496	  protected getPromise<T extends MessageContent>(
497	    msg: WorkerRequest,
498	  ): Promise<T> {
499	    const uuid = msg.uuid;
500	    const executor = (
501	      resolve: (arg: T) => void,
502	      reject: (arg: any) => void,
503	    ) => {
504	      const cb = (msg: WorkerResponse) => {
505	        if (msg.kind == "return") {
506	          resolve(msg.content as T);
507	        } else {
508	          if (msg.kind != "throw") {
509	            reject("Uknown msg kind " + msg.kind);
510	          } else {
511	            reject(msg.content);
512	          }
513	        }
514	      };
515	      this.pendingPromise.set(uuid, cb);
516	    };
517	    const promise = new Promise<T>(executor);
518	    this.worker.postMessage(msg);
519	    return promise;
520	  }
521	
522	  async reload(
523	    modelId: string | string[],
524	    chatOpts?: ChatOptions | ChatOptions[],
525	  ): Promise<void> {
526	    // Always convert modelId and chatOpts to lists internally for ease of manipulation
527	    if (!Array.isArray(modelId)) {
528	      modelId = [modelId];
529	    }
530	    if (chatOpts !== undefined && !Array.isArray(chatOpts)) {
531	      chatOpts = [chatOpts];
532	    }
533	
534	    const msg: WorkerRequest = {
535	      kind: "reload",
536	      uuid: crypto.randomUUID(),
537	      content: {
538	        modelId: modelId,
539	        chatOpts: chatOpts,
540	      },
541	    };
542	    await this.getPromise<null>(msg);
543	    this.modelId = modelId;
544	    this.chatOpts = chatOpts;
545	  }
546	
547	  async getMaxStorageBufferBindingSize(): Promise<number> {
548	    const msg: WorkerRequest = {
549	      kind: "getMaxStorageBufferBindingSize",
550	      uuid: crypto.randomUUID(),
551	      content: null,
552	    };
553	    return await this.getPromise<number>(msg);
554	  }
555	
556	  async getGPUVendor(): Promise<string> {
557	    const msg: WorkerRequest = {
558	      kind: "getGPUVendor",
559	      uuid: crypto.randomUUID(),
560	      content: null,
561	    };
562	    return await this.getPromise<string>(msg);
563	  }
564	
565	  async getMessage(modelId?: string): Promise<string> {
566	    const msg: WorkerRequest = {
567	      kind: "getMessage",
568	      uuid: crypto.randomUUID(),
569	      content: {
570	        modelId: modelId,
571	      },
572	    };
573	    return await this.getPromise<string>(msg);
574	  }
575	
576	  async runtimeStatsText(modelId?: string): Promise<string> {
577	    const msg: WorkerRequest = {
578	      kind: "runtimeStatsText",
579	      uuid: crypto.randomUUID(),
580	      content: {
581	        modelId: modelId,
582	      },
583	    };
584	    return await this.getPromise<string>(msg);
585	  }
586	
587	  interruptGenerate(): void {
588	    const msg: WorkerRequest = {
589	      kind: "interruptGenerate",
590	      uuid: crypto.randomUUID(),
591	      content: null,
592	    };
593	    this.getPromise<null>(msg);
594	  }
595	
596	  async unload(): Promise<void> {
597	    const msg: WorkerRequest = {
598	      kind: "unload",
599	      uuid: crypto.randomUUID(),
600	      content: null,
601	    };
602	    await this.getPromise<null>(msg);
603	    this.modelId = undefined;
604	    this.chatOpts = undefined;
605	  }
606	
607	  async resetChat(keepStats = false, modelId?: string): Promise<void> {
608	    const msg: WorkerRequest = {
609	      kind: "resetChat",
610	      uuid: crypto.randomUUID(),
611	      content: {
612	        keepStats: keepStats,
613	        modelId: modelId,
614	      },
615	    };
616	    await this.getPromise<null>(msg);
617	  }
618	
619	  async forwardTokensAndSample(
620	    inputIds: Array<number>,
621	    isPrefill: boolean,
622	    modelId?: string,
623	  ): Promise<number> {
624	    const msg: WorkerRequest = {
625	      kind: "forwardTokensAndSample",
626	      uuid: crypto.randomUUID(),
627	      content: {
628	        inputIds: inputIds,
629	        isPrefill: isPrefill,
630	        modelId: modelId,
631	      },
632	    };
633	    return await this.getPromise<number>(msg);
634	  }
635	
636	  /**
637	   * Every time the generator is called, we post a message to the worker asking it to
638	   * decode one step, and we expect to receive a message of `ChatCompletionChunk` from
639	   * the worker which we yield. The last message is `void`, meaning the generator has nothing
640	   * to yield anymore.
641	   *
642	   * @param selectedModelId: The model of whose async generator to call next() to get next chunk.
643	   *   Needed because an engine can load multiple models.
644	   *
645	   * @note ChatCompletion and Completion share the same chunk generator.
646	   */
647	  async *asyncGenerate(
648	    selectedModelId: string,
649	  ): AsyncGenerator<ChatCompletionChunk | Completion, void, void> {
650	    // Every time it gets called, sends message to worker, asking for the next chunk
651	    while (true) {
652	      const msg: WorkerRequest = {
653	        kind: "completionStreamNextChunk",
654	        uuid: crypto.randomUUID(),
655	        content: {
656	          selectedModelId: selectedModelId,
657	        } as CompletionStreamNextChunkParams,
658	      };
659	      const ret = await this.getPromise<ChatCompletionChunk>(msg);
660	      // If the worker's generator reached the end, it would return a `void`
661	      if (typeof ret !== "object") {
662	        break;
663	      }
664	      yield ret;
665	    }
666	  }
667	
668	  async chatCompletion(
669	    request: ChatCompletionRequestNonStreaming,
670	  ): Promise<ChatCompletion>;
671	  async chatCompletion(
672	    request: ChatCompletionRequestStreaming,
673	  ): Promise<AsyncIterable<ChatCompletionChunk>>;
674	  async chatCompletion(
675	    request: ChatCompletionRequestBase,
676	  ): Promise<AsyncIterable<ChatCompletionChunk> | ChatCompletion>;
677	  async chatCompletion(
678	    request: ChatCompletionRequest,
679	  ): Promise<AsyncIterable<ChatCompletionChunk> | ChatCompletion> {
680	    if (this.modelId === undefined) {
681	      throw new WorkerEngineModelNotLoadedError(this.constructor.name);
682	    }
683	    // Needed for the streaming case. Consolidate model id to specify
684	    // which model's asyncGenerator to instantiate or call next() on.
685	    // Since handler can maintain multiple generators concurrently
686	    const selectedModelId = getModelIdToUse(
687	      this.modelId ? this.modelId : [],
688	      request.model,
689	      "ChatCompletionRequest",
690	    );
691	
692	    if (request.stream) {
693	      // First let worker instantiate a generator
694	      const msg: WorkerRequest = {
695	        kind: "chatCompletionStreamInit",
696	        uuid: crypto.randomUUID(),
697	        content: {
698	          request: request,
699	          selectedModelId: selectedModelId,
700	          modelId: this.modelId,
701	          chatOpts: this.chatOpts,
702	        },
703	      };
704	      await this.getPromise<null>(msg);
705	
706	      // Then return an async chunk generator that resides on the client side
707	      return this.asyncGenerate(selectedModelId) as AsyncGenerator<
708	        ChatCompletionChunk,
709	        void,
710	        void
711	      >;
712	    }
713	
714	    // Non streaming case is more straightforward
715	    const msg: WorkerRequest = {
716	      kind: "chatCompletionNonStreaming",
717	      uuid: crypto.randomUUID(),
718	      content: {
719	        request: request,
720	        modelId: this.modelId,
721	        chatOpts: this.chatOpts,
722	      },
723	    };
724	    return await this.getPromise<ChatCompletion>(msg);
725	  }
726	
727	  async completion(
728	    request: CompletionCreateParamsNonStreaming,
729	  ): Promise<Completion>;
730	  async completion(
731	    request: CompletionCreateParamsStreaming,
732	  ): Promise<AsyncIterable<Completion>>;
733	  async completion(
734	    request: CompletionCreateParamsBase,
735	  ): Promise<AsyncIterable<Completion> | Completion>;
736	  async completion(
737	    request: CompletionCreateParams,
738	  ): Promise<AsyncIterable<Completion> | Completion> {
739	    if (this.modelId === undefined) {
740	      throw new WorkerEngineModelNotLoadedError(this.constructor.name);
741	    }
742	    // Needed for the streaming case. Consolidate model id to specify
743	    // which model's asyncGenerator to instantiate or call next() on.
744	    // Since handler can maintain multiple generators concurrently
745	    const selectedModelId = getModelIdToUse(
746	      this.modelId ? this.modelId : [],
747	      request.model,
748	      "CompletionCreateParams",
749	    );
750	
751	    if (request.stream) {
752	      // First let worker instantiate a generator
753	      const msg: WorkerRequest = {
754	        kind: "completionStreamInit",
755	        uuid: crypto.randomUUID(),
756	        content: {
757	          request: request,
758	          selectedModelId: selectedModelId,
759	          modelId: this.modelId,
760	          chatOpts: this.chatOpts,
761	        },
762	      };
763	      await this.getPromise<null>(msg);
764	
765	      // Then return an async chunk generator that resides on the client side
766	      return this.asyncGenerate(selectedModelId) as AsyncGenerator<
767	        Completion,
768	        void,
769	        void
770	      >;
771	    }
772	
773	    // Non streaming case is more straightforward
774	    const msg: WorkerRequest = {
775	      kind: "completionNonStreaming",
776	      uuid: crypto.randomUUID(),
777	      content: {
778	        request: request,
779	        modelId: this.modelId,
780	        chatOpts: this.chatOpts,
781	      },
782	    };
783	    return await this.getPromise<Completion>(msg);
784	  }
785	
786	  async embedding(
787	    request: EmbeddingCreateParams,
788	  ): Promise<CreateEmbeddingResponse> {
789	    if (this.modelId === undefined) {
790	      throw new WorkerEngineModelNotLoadedError(this.constructor.name);
791	    }
792	    const msg: WorkerRequest = {
793	      kind: "embedding",
794	      uuid: crypto.randomUUID(),
795	      content: {
796	        request: request,
797	        modelId: this.modelId,
798	        chatOpts: this.chatOpts,
799	      },
800	    };
801	    return await this.getPromise<CreateEmbeddingResponse>(msg);
802	  }
803	
804	  onmessage(event: any) {
805	    let msg: WorkerResponse;
806	    if (event instanceof MessageEvent) {
807	      msg = event.data as WorkerResponse;
808	    } else {
809	      msg = event as WorkerResponse;
810	    }
811	    switch (msg.kind) {
812	      case "initProgressCallback": {
813	        if (this.initProgressCallback !== undefined) {
814	          this.initProgressCallback(msg.content as InitProgressReport);
815	        }
816	        return;
817	      }
818	      case "return": {
819	        const cb = this.pendingPromise.get(msg.uuid);
820	        if (cb === undefined) {
821	          throw Error("return from a unknown uuid msg=" + msg.uuid);
822	        }
823	        this.pendingPromise.delete(msg.uuid);
824	        cb(msg);
825	        return;
826	      }
827	      case "throw": {
828	        const cb = this.pendingPromise.get(msg.uuid);
829	        if (cb === undefined) {
830	          throw Error("return from a unknown uuid, msg=" + msg);
831	        }
832	        this.pendingPromise.delete(msg.uuid);
833	        cb(msg);
834	        return;
835	      }
836	      default: {
837	        const unknownMsg = msg as any;
838	        throw new UnknownMessageKindError(unknownMsg.kind, unknownMsg.content);
839	      }
840	    }
841	  }
842	}
