20	/**
21	 * Based on `p_prob` of size (vocabSize,) which becomes a distribution after calling
22	 * `applySoftmaxWithTemperature()`, sample `top_logprobs` top-probable tokens.
23	 *
24	 * @param num_top_probs: `top_logprobs` from ChatCompletionRequest
25	 * @param p_prob: `logitsOnCPUArray`, being a distribution after `applySoftmaxWithTemperature()`.
26	 *
27	 * Followed implementation of `ComputeTopProbsImpl()` from [https://github.com/mlc-ai/mlc-llm/blob/
28	 * 5b8c529e9704abd09b0432da6dcb4b013fdf43b1/cpp/serve/sampler/cpu_sampler.cc].
29	 *
30	 * @returns Arrays of (tokenID, prob) pairs, ranked from highest prob to least.
31	 */
32	export function getTopProbs(
33	  num_top_probs: number,
34	  p_prob: Float32Array,
35	): Array<[number, number]> {
36	  if (num_top_probs == 0) return [];
37	  // Initialize to dummy values
38	  const top_probs: Array<[number, number]> = [];
39	  const ndata = p_prob.length;
40	  for (let i = 0; i < num_top_probs; i++) {
41	    top_probs.push([-1, -1.0]);
42	  }
43	
44	  let sum_prob = 0.0;
45	  // Selection argsort.
46	  for (let p = 0; p < ndata; p++) {
47	    let i = num_top_probs - 1;
48	    for (; i >= 0; --i) {
49	      if (p_prob[p] > top_probs[i][1]) {
50	        if (i !== num_top_probs - 1) {
51	          top_probs[i + 1] = top_probs[i];
52	        }
53	      } else {
54	        break;
55	      }
56	    }
57	    if (i !== num_top_probs - 1) {
58	      top_probs[i + 1] = [p, p_prob[p]];
59	    }
60	
61	    // Early exit
62	    sum_prob += p_prob[p];
63	    if (1 - sum_prob <= top_probs[num_top_probs - 1][1]) {
64	      break;
65	    }
66	  }
67	  return top_probs;
68	}
69	
70	/**
71	 * Get the token table in the form of a string list of tokens, ordered by their token id.
72	 * @param tokenizer A loaded tokenizer.
73	 * @note The size of the table (i.e. tokenizer.getVocabSize()) may be smaller than the `vocab_size`
74	 * in config.json (length of logits), see https://github.com/QwenLM/Qwen2/issues/147 and
75	 * https://huggingface.co/microsoft/Phi-3-mini-4k-instruct/discussions/47.
76	 */
77	export function getTokenTableFromTokenizer(tokenizer: Tokenizer): string[] {
78	  const tokenTable: string[] = [];
79	  const vocabSize = tokenizer.getVocabSize();
80	  for (let tokenId = 0; tokenId < vocabSize; tokenId++) {
81	    tokenTable.push(tokenizer.idToToken(tokenId));
82	  }
83	  return tokenTable;
84	}
85	
86	/**
87	 * Postprocess the suffix of ModelRecord.model to be "/resolve/main/" if it is not specified otherwise.
88	 * e.g. https://huggingface.co/mlc-ai/OpenHermes-2.5-Mistral-7B-q4f16_1-MLC/resolve/main/
89	 * @return the href of the final URL.
90	 */
91	export function cleanModelUrl(modelUrl: string): string {
92	  // https://huggingface.co/USER/MODEL -> https://huggingface.co/USER/MODEL/
93	  modelUrl += modelUrl.endsWith("/") ? "" : "/";
94	  if (!modelUrl.match(/.+\/resolve\/.+\//)) modelUrl += "resolve/main/";
95	  // https://huggingface.co/USER/MODEL/ -> https://huggingface.co/USER/MODEL/resolve/main/
96	  return new URL(modelUrl).href;
97	}
98	
99	// Constants for Hermes-2-Pro / Hermes-3 models function calling
100	// Follows https://huggingface.co/NousResearch/Hermes-2-Pro-Llama-3-8B#prompt-format-for-function-calling
101	//         https://huggingface.co/NousResearch/Hermes-3-Llama-3.1-8B#prompt-format-for-function-calling
102	
103	/**
104	 * Json schema used to prompt the model for function calling; directly copied from the official guide.
