419	 */
420	export async function getImageDataFromURL(url: string): Promise<ImageData> {
421	  const response = await fetch(url, { mode: "cors" });
422	  const img = await createImageBitmap(await response.blob());
423	  const canvas = new OffscreenCanvas(img.width, img.height);
424	  const ctx = canvas.getContext("2d");
425	  if (!ctx) {
426	    throw new Error("Could not get 2d context");
427	  }
428	  ctx.drawImage(img, 0, 0);
429	
430	  const imageData = ctx.getImageData(0, 0, img.width, img.height);
431	  return imageData;
432	}
