434	/**
435	 * Given an ImageData, return the RGB array in Uint8ClampedArray. Note the ImageData.data
436	 * is RGBA, so we skip every fourth element of the data. The order goes by rows from the
437	 * top-left pixel to the bottom-right, in RGB order.
438	 */
439	export function getRGBArrayFromImageData(
440	  imageData: ImageData,
441	): Uint8ClampedArray {
442	  const newData = new Uint8ClampedArray(imageData.width * imageData.height * 3);
443	  for (let i = 0, offset = 0; i < imageData.data.length; i += 4) {
444	    newData[offset++] = imageData.data[i];
445	    newData[offset++] = imageData.data[i + 1];
446	    newData[offset++] = imageData.data[i + 2];
447	  }
448	  return newData;
449	}
